entries[26872] = { ["name"] = "Figur - Jadeeule", ["text"] = "Wirken in 12.5 sek.\nTools: Juweliersset\nReagenzien:\nJade (4), Echtsilberbarren (2), Visionenstaub (4), Filigranarbeit aus Mithril (4)\nFigur - Jadeeule\nWird beim Aufheben gebunden\nEinzigartig anlegbarSchmuck\n+3 Intelligenz\n+2 Willenskraft\n35\nBenötigt Juwelenschleifen\n(200)\nBenutzen: Stellt 12 Sek. lang pro Sekunde 30 Mana wieder her. (5 Min Abklingzeit)" }
entries[26873] = { ["name"] = "Figur - Goldener Hase", ["text"] = "Wirken in 12.5 sek.\nTools: Juweliersset\nReagenzien:\nGoldbarren (6), Citrin (2)\nFigur - Goldener Hase\nWird beim Aufheben gebunden\nEinzigartig anlegbarSchmuck\n35\nBenötigt Juwelenschleifen\n(200)\nAnlegen: Lauftempo ein wenig erhöht.\nBenutzen: Erhöht das Bewegungstempo um 30% und verhindert, dass der Benutzer von weiteren Verlangsamungseffekten betroffen wird. Hält 6 Sek. lang an. (20 Min Abklingzeit)" }
