entries[27585] = { ["name"] = "Schwerer Obsidiangürtel", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer\nReagenzien:\nKleiner Obsidiansplitter (14), Verzauberter Thoriumbarren (4), Essenz der Erde (2)\nSchwerer Obsidiangürtel\nWird beim Anlegen gebunden\nTaille Platte\n352 Rüstung\n+25 Stärke\nHaltbarkeit 45 / 45\n60\nAnlegen: +5 Alle Widerstandsarten." }
entries[27586] = { ["name"] = "Gezackter Obsidianschild", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer\nReagenzien:\nGroßer Obsidiansplitter (8), Kleiner Obsidiansplitter (24), Verzauberter Thoriumbarren (8), Essenz der Erde (4)\nGezackter Obsidianschild\nWird beim Anlegen gebunden\nSchildhand Schild\n2209 Rüstung\nHaltbarkeit 120 / 120\n60\nAnlegen: Erhöht Eure Ausweichwertung um 9.\nAnlegen: +5 Alle Widerstandsarten.\nAnlegen: Bei einem Treffer durch einen gegnerischen Zauber besteht eine Chance von 5%, dass der Angreifer 3 Sek. zum Schweigen gebracht wird. (Procchance: 5%, 20s Abklingzeit)" }
entries[27587] = { ["name"] = "Dicke Obsidianbrustplatte", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer\nReagenzien:\nGroßer Obsidiansplitter (18), Kleiner Obsidiansplitter (40), Verzauberter Thoriumbarren (12), Essenz der Erde (10), Gewaltiger Smaragd (4)\nDicke Obsidianbrustplatte\nWird beim Anlegen gebunden\nBrust Platte\n796 Rüstung\n+38 Stärke\n+16 Ausdauer\nHaltbarkeit 165 / 165\n60\nAnlegen: Bei einem Treffer durch einen Schadenszauber, der unregelmäßigen Schaden zufügt, besteht eine Chance von 30%, 6 Sek. lang einen Zauberschild zu aktivieren, der 300 to 500 Schaden der entsprechenden Schadenskategorie absorbiert. (Procchance: 30%, 10s Abklingzeit)" }
entries[27588] = { ["name"] = "Leichter Obsidiangürtel", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer\nReagenzien:\nKleiner Obsidiansplitter (14), Verzaubertes Leder (4)\nLeichter Obsidiangürtel\nWird beim Anlegen gebunden\nTaille Kette\n238 Rüstung\n+16 Beweglichkeit\nHaltbarkeit 45 / 45\n60\nAnlegen: Erhöht die kritische Trefferwertung um 14.\nAnlegen: +5 Alle Widerstandsarten." }
entries[27589] = { ["name"] = "Dunkler Griff des Zerstörers", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer\nReagenzien:\nGroßer Obsidiansplitter (8), Kleiner Obsidiansplitter (24), Verzaubertes Leder (8), Fläschchen der obersten Macht\nDunkler Griff des Zerstörers\nWird beim Anlegen gebunden\nHände Kette\n334 Rüstung\n+14 Beweglichkeit\nHaltbarkeit 55 / 55\n60\nAnlegen: Erhöht die kritische Trefferwertung um 14.\nAnlegen: Bei einem erfolgreichen Nahkampf- oder Distanzangriff erhaltet Ihr 8 Mana, während dem Ziel 8 Mana entzogen werden." }
entries[27590] = { ["name"] = "Obsidianpanzertunika", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer\nReagenzien:\nGroßer Obsidiansplitter (15), Kleiner Obsidiansplitter (36), Verzaubertes Leder (12), Wächterstein (10), Azerothischer Diamant (4)\nObsidianpanzertunika\nWird beim Anlegen gebunden\nBrust Kette\n542 Rüstung\n+38 Beweglichkeit\nHaltbarkeit 165 / 165\n60\nAnlegen: Erhöht die kritische Trefferwertung um 14.\nAnlegen: Der erlittene Zauberschaden wird um 10 verringert." }
