entries[27605] = { ["name"] = "Schattenwort: Schmerz", ["text"] = "470 Mana 30 Meter Reichweite\nSofort\nEin Wort der Dunkelheit, das 18 Sek. lang insgesamt 852 Schattenschaden zufügt." }
entries[27606] = { ["name"] = "Erneuerung", ["text"] = "365 Mana 40 Meter Reichweite\nSofort\nHeilt das Ziel 15 Sek. lang um 810 Schaden." }
entries[27607] = { ["name"] = "Machtwort: Schild", ["text"] = "500 Mana 40 Meter Reichweite\nSofort 4 sek. Abklingzeit\nNutzt die Seelenkraft des Gruppenmitglieds zum Abschirmen und absorbiert dabei 964 Schaden. Hält 30 Sek. lang an. Solange der Schild hält, wird das Zauberwirken durch erlittenen Schaden nicht unterbrochen. Nachdem das Ziel einmal abgeschirmt wurde, kann es 15 Sek. lang nicht wieder abgeschirmt werden." }
entries[27608] = { ["name"] = "Blitzheilung", ["text"] = "380 Mana 40 Meter Reichweite\nWirken in 1.5 sek.\nHeilt ein befreundetes Ziel um 833 to 979." }
entries[27609] = { ["name"] = "Magiebannung", ["text"] = "18% von Grundmana 30 Meter Reichweite\nSofort\nBannt auf dem Ziel liegende Magie und entfernt 2 schädliche Zauber von einem Freund oder 2 nützliche Zauber von einem Feind." }
entries[27610] = { ["name"] = "Psychischer Schrei", ["text"] = "210 Mana\nSofort 30 sek. Abklingzeit\nStößt einen psychischen Schrei aus, der 5 Sek. lang 5 Feinde in einem Umkreis von 8 Metern in die Flucht schlägt. Erlittener Schaden kann den Effekt unterbrechen." }
entries[27611] = { ["name"] = "Ausweiden", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe" }
entries[27613] = { ["name"] = "Tritt", ["text"] = "Nahkampfreichweite\nSofort\nTritt einen Feind, fügt ihm 2 Schaden zu und unterbricht 4 Sek. lang den gewirkten Zauber." }
entries[27614] = { ["name"] = "Dungeon Set 2.0 Geister" }
entries[27615] = { ["name"] = "Nierenhieb", ["text"] = "Nahkampfreichweite\nSofort 20 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nFinishing-Move, der das Ziel betäubt." }
entries[27616] = { ["name"] = "Extradimensionaler Geisterdetektor", ["text"] = "Sofort\nErmöglicht es Euch, die Geister der kürzlich Verstorbenen zu sehen." }
entries[27617] = { ["name"] = "Verschwinden", ["text"] = "Sofort 5 min Abklingzeit" }
entries[27618] = { ["name"] = "Blizzard", ["text"] = "1400 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 8 sek.)\nEisbrocken prasseln auf das Zielgebiet nieder und verursachen 8 Sek. lang insgesamt 1192 Frostschaden." }
entries[27619] = { ["name"] = "Eisblock", ["text"] = "15 Mana\nSofort 5 min Abklingzeit\nIhr werdet in einen Eisblock eingehüllt, der Euch 10 Sek. lang vor allen körperlichen Angriffen und Zaubern schützt, allerdings könnt Ihr während dieser Zeit weder angreifen noch Euch bewegen und auch keine Zauber wirken." }
entries[27620] = { ["name"] = "Schnapptritt", ["text"] = "Nahkampfreichweite\nSofort\nTritt einen Feind, fügt ihm 2 Schaden zu und unterbricht 4 Sek. lang den gewirkten Zauber." }
entries[27621] = { ["name"] = "Totem des Windzorns", ["text"] = "250 Mana\nSofort\nBeschwört ein Totem des Windzorns mit 5 Gesundheit zu Füßen des Zaubernden. Das Totem verzaubert die Waffenhandwaffen aller Gruppenmitglieder mit Wind, wenn sie sich im Umkreis von 0 Metern aufhalten. Bei jedem Treffer besteht eine Chance von 20%, dass der Angreifer 5 zusätzliche Angriffe mit 5 zusätzlicher Angriffskraft erhält. Hält 1.50 Min. lang an." }
entries[27622] = { ["name"] = "Get the Key: Vaelen's Invisibility & See Invisibility" }
entries[27623] = { ["name"] = "Totem der Feuernova", ["text"] = "640 Mana\nSofort 15 sek. Abklingzeit\nBeschwört ein Totem der Feuernova mit 5 Gesundheit, das 5 Sek. lang anhält. Wenn es nicht innerhalb von 5 Sek. zerstört wird, fügt das Totem Feinden in einem Umkreis von 0 Metern 5 Feuerschaden zu." }
entries[27624] = { ["name"] = "Geringe Welle der Heilung", ["text"] = "380 Mana 40 Meter Reichweite\nWirken in 1.5 sek.\nHeilt ein befreundetes Ziel um 853 to 949." }
entries[27626] = { ["name"] = "Reinigen", ["text"] = "5% von Grundmana 30 Meter Reichweite\nSofort\nReinigt das feindliche Ziel und entzieht 2 nützliche magische Effekte." }
entries[27632] = { ["name"] = "Gezielter Schuss", ["text"] = "310 Mana 35 Meter Reichweite\nWirken in 3 sek. 6 sek. Abklingzeit\nBenötigt Distanzwaffe\nEin gezielter Schuss, der den Distanzschaden um 600 erhöht." }
entries[27633] = { ["name"] = "Zurechtstutzen", ["text"] = "80 Mana Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nVerursacht 50 Schaden und reduziert 10 Sek. lang das Bewegungstempo des feindlichen Ziels um 60%." }
entries[27634] = { ["name"] = "Erschütternder Schuss", ["text"] = "35 Meter Reichweite\nBenötigt Distanzwaffe\nMacht einen Feind benommen und verringert sein Bewegungstempo 3 Sek. lang um 50%.\n(Procchance: 40%)" }
entries[27635] = { ["name"] = "Blitzschlagschild", ["text"] = "30 Meter Reichweite\nSofort\nSchleudert einen Blitz auf das Ziel und fügt ihm 50 Naturschaden zu." }
entries[27636] = { ["name"] = "Sternensplitter", ["text"] = "500 Mana 100 Meter Reichweite\nKanalisiert (Wirken in 6 sek.)\nLässt Sternensplitter auf den Kopf des feindlichen Ziels regnen und verursacht 6 Sek. lang insgesamt 3000 Arkanschaden." }
entries[27637] = { ["name"] = "Nachwachsen", ["text"] = "250 Mana 40 Meter Reichweite\nWirken in 2 sek.\nHeilt einen Verbündeten um einen festgelegten Wert und heilt dann 21 Sek. lang alle 3 Sek. weiteren Schaden." }
entries[27638] = { ["name"] = "Krallenhieb", ["text"] = "Nahkampfreichweite\nSofort\nAttackiert das Ziel mit Krallen, fügt 200 to 300 Schaden sowie 500 zusätzlichen Schaden im Verlauf von 15 Sek. zu." }
entries[27639] = { ["name"] = "Tier rufen", ["text"] = "Sofort\nRuft Isaliens Hippogryph herbei, damit er sie im Kampf unterstützt." }
entries[27640] = { ["name"] = "Baron Totenschwurs Seelenentzug", ["text"] = "60 Mana 20 Meter Reichweite\nKanalisiert (Wirken in 3 sek.)\nFügt einem Feind Schattenschaden zu und verringert 3 Sek. lang sein Bewegungstempo." }
entries[27641] = { ["name"] = "Furcht", ["text"] = "20 Meter Reichweite\nWirken in 1 sek.\nErfüllt einen Feind mit Furcht, woraufhin er bis zu 6 Sek. lang voller Schrecken flüchtet." }
