entries[27829] = { ["name"] = "Gamaschen der Titanen", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer\nReagenzien:\nArkanitbarren (12), Verzauberter Thoriumbarren (20), Essenz der Erde (10), Fläschchen der Titanen (2)\nGamaschen der Titanen\nWird beim Anlegen gebunden\nBeine Platte\n653 Rüstung\n+30 Stärke\nHaltbarkeit 120 / 120\n55\nAnlegen: Erhöht die kritische Trefferwertung um 14.\nAnlegen: Erhöht die Trefferwertung um 20." }
entries[27830] = { ["name"] = "Willensbrecher", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer\nReagenzien:\nArkanitbarren (15), Dunkeleisenbarren (10), Essenz des Untodes (20), Dunkelrune (20), Teufelssaurierleder (10)\nWillensbrecher\nWird beim Anlegen gebunden\nEinhändig Streitkolben\n86 - 161 Schaden Tempo 2.70\n(45.74 Schaden pro Sekunde)\nHaltbarkeit 105 / 105\n58\nAnlegen: Erhöht die kritische Trefferwertung um 14.\nAnlegen: Erhöht die Trefferwertung um 10." }
