entries[27832] = { ["name"] = "Weisenklinge", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer\nReagenzien:\nArkanitbarren (12), Nexuskristall (2), Fläschchen der obersten Macht (2), Verzaubertes Leder (4)\nWeisenklinge\nWird beim Anlegen gebunden\nWaffenhand Schwert\n58 - 109 Schaden Tempo 1.80\n(46.39 Schaden pro Sekunde)\n+17 Ausdauer\nHaltbarkeit 105 / 105\n59\nAnlegen: Erhöht die Zaubermacht um 25.\nAnlegen: Erhöht den Zauberdurchschlag um 10." }
